// GENERATED by pxl-tool/bin/spec.rs from color.json — do not edit.
//
// The color of every look and every placed color: what a cube *is* to
// the eye when no texture is drawn over it — everything drawn with the
// pack off reads this, the coarse tiers included, which summarize it
// the way they summarize the tiles with the pack on
// (pxl-render mesh/chunk.rs). A texture pack decorates these; it
// does not replace them.

// Casing here is the spec's and not Rust's: a name is spelled as the JSON
// spells it, so that one record is indexed by one name on both sides. To
// case them the way Rust would is to rename the protocol.

use super::cube::cubes;
use super::Swatch;

/// `sentinel`'s color for a value.
pub const fn sentinel(t: u8) -> Option<Swatch> {
    match t {
        // A cell whose data is missing or invalid, a visible neutral gray so it reads as not known rather than as whatever drew last.
        cubes::sentinel::unknown => Some(Swatch::new(0xd9d0cc)),
        _ => None,
    }
}

